[metadata] {"type": "create", "filePath": "/app/output/fintech_disruption.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Fintech Disruption: Traditional Banking vs Digital Finance 2015–2024</title>
<link href="https://fonts.googleapis.com/css2?family=Instrument+Serif:ital@0;1&family=IBM+Plex+Sans:wght@300;400;500;600;700&family=IBM+Plex+Mono:wght@400;500&display=swap" rel="stylesheet">
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js"></script>
<style>
  :root {
    --bg: #0d1117;
    --surface: #161b22;
    --surface-raised: #1c2230;
    --border: rgba(255,255,255,0.07);
    --border-accent: rgba(212,167,58,0.3);
    --text: #e6edf3;
    --text-dim: #7d8590;
    --text-muted: #484f58;
    --gold: #d4a73a;
    --gold-dim: rgba(212,167,58,0.12);
    --gold-mid: rgba(212,167,58,0.22);
    --teal: #1a7f9c;
    --teal-bright: #2cc6ef;
    --teal-dim: rgba(26,127,156,0.15);
    --rose: #c94f6d;
    --rose-dim: rgba(201,79,109,0.15);
    --sage: #4a9068;
    --sage-dim: rgba(74,144,104,0.12);
    --amber: #e07b2e;
    --amber-dim: rgba(224,123,46,0.12);
    --font-body: 'IBM Plex Sans', system-ui, sans-serif;
    --font-display: 'Instrument Serif', Georgia, serif;
    --font-mono: 'IBM Plex Mono', 'Courier New', monospace;
  }

  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

  body {
    background: var(--bg);
    background-image:
      radial-gradient(ellipse 80% 40% at 50% 0%, rgba(212,167,58,0.04) 0%, transparent 60%),
      radial-gradient(ellipse 60% 30% at 80% 80%, rgba(26,127,156,0.05) 0%, transparent 50%);
    color: var(--text);
    font-family: var(--font-body);
    font-size: 14px;
    line-height: 1.6;
    min-height: 100vh;
  }

  .page {
    max-width: 1280px;
    margin: 0 auto;
    padding: 48px 32px 64px;
  }

  /* ─── Header ─── */
  .header {
    border-bottom: 1px solid var(--border-accent);
    padding-bottom: 32px;
    margin-bottom: 48px;
  }

  .header-eyebrow {
    font-family: var(--font-mono);
    font-size: 11px;
    font-weight: 500;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    color: var(--gold);
    margin-bottom: 12px;
    display: flex;
    align-items: center;
    gap: 10px;
  }

  .header-eyebrow::before {
    content: '';
    display: inline-block;
    width: 24px;
    height: 1px;
    background: var(--gold);
  }

  .header h1 {
    font-family: var(--font-display);
    font-size: 42px;
    font-weight: 400;
    font-style: italic;
    line-height: 1.15;
    color: var(--text);
    margin-bottom: 14px;
  }

  .header h1 em {
    color: var(--gold);
    font-style: italic;
  }

  .header-sub {
    font-size: 15px;
    color: var(--text-dim);
    font-weight: 300;
    max-width: 700px;
  }

  .header-meta {
    display: flex;
    gap: 32px;
    margin-top: 20px;
    flex-wrap: wrap;
  }

  .meta-item {
    display: flex;
    flex-direction: column;
    gap: 3px;
  }

  .meta-label {
    font-family: var(--font-mono);
    font-size: 10px;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    color: var(--text-muted);
  }

  .meta-value {
    font-size: 13px;
    font-weight: 600;
    color: var(--text-dim);
  }

  /* ─── Stat row ─── */
  .kpi-strip {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 16px;
    margin-bottom: 48px;
  }

  .kpi-card {
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 6px;
    padding: 20px 22px;
    position: relative;
    overflow: hidden;
  }

  .kpi-card::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 2px;
  }

  .kpi-card.gold::before { background: var(--gold); }
  .kpi-card.teal::before { background: var(--teal-bright); }
  .kpi-card.rose::before { background: var(--rose); }
  .kpi-card.sage::before { background: var(--sage); }

  .kpi-label {
    font-family: var(--font-mono);
    font-size: 10px;
    letter-spacing: 0.09em;
    text-transform: uppercase;
    color: var(--text-dim);
    margin-bottom: 8px;
  }

  .kpi-value {
    font-family: var(--font-display);
    font-size: 36px;
    font-style: italic;
    line-height: 1;
    margin-bottom: 6px;
  }

  .kpi-card.gold .kpi-value { color: var(--gold); }
  .kpi-card.teal .kpi-value { color: var(--teal-bright); }
  .kpi-card.rose .kpi-value { color: var(--rose); }
  .kpi-card.sage .kpi-value { color: var(--sage); }

  .kpi-delta {
    font-size: 11px;
    color: var(--text-muted);
  }

  .kpi-delta strong {
    font-weight: 600;
  }

  /* ─── Chart grid ─── */
  .chart-grid {
    display: grid;
    gap: 24px;
    margin-bottom: 24px;
  }

  .chart-grid-2 {
    grid-template-columns: 1fr 1fr;
  }

  .chart-grid-3 {
    grid-template-columns: 3fr 2fr;
  }

  .chart-panel {
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 8px;
    padding: 28px;
    position: relative;
  }

  .panel-header {
    margin-bottom: 20px;
  }

  .panel-insight-id {
    font-family: var(--font-mono);
    font-size: 10px;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    color: var(--text-muted);
    margin-bottom: 6px;
  }

  .panel-title {
    font-family: var(--font-body);
    font-size: 15px;
    font-weight: 600;
    color: var(--text);
    line-height: 1.3;
    margin-bottom: 6px;
  }

  .panel-desc {
    font-size: 12px;
    color: var(--text-dim);
    line-height: 1.5;
  }

  .chart-wrap {
    position: relative;
    width: 100%;
  }

  .annotation-band {
    position: absolute;
    background: rgba(201,79,109,0.07);
    border-left: 2px solid rgba(201,79,109,0.5);
    border-right: 2px solid rgba(201,79,109,0.5);
    top: 0;
    bottom: 0;
    pointer-events: none;
  }

  /* ─── Legend ─── */
  .legend {
    display: flex;
    flex-wrap: wrap;
    gap: 16px;
    margin-top: 16px;
  }

  .legend-item {
    display: flex;
    align-items: center;
    gap: 7px;
    font-size: 11px;
    color: var(--text-dim);
  }

  .legend-dot {
    width: 10px;
    height: 10px;
    border-radius: 50%;
    flex-shrink: 0;
  }

  .legend-line {
    width: 24px;
    height: 2px;
    flex-shrink: 0;
  }

  .legend-dash {
    width: 24px;
    height: 2px;
    flex-shrink: 0;
    background: repeating-linear-gradient(to right, currentColor 0 4px, transparent 4px 8px);
  }

  /* ─── Annotations ─── */
  .callout-row {
    display: flex;
    gap: 12px;
    margin-top: 14px;
    flex-wrap: wrap;
  }

  .callout {
    display: inline-flex;
    align-items: flex-start;
    gap: 8px;
    background: var(--gold-dim);
    border: 1px solid var(--border-accent);
    border-radius: 4px;
    padding: 8px 12px;
    font-size: 11px;
    color: var(--text-dim);
    line-height: 1.4;
    max-width: 280px;
  }

  .callout.teal {
    background: var(--teal-dim);
    border-color: rgba(44,198,239,0.2);
  }

  .callout.rose {
    background: var(--rose-dim);
