      --text: #1a1a1a;
      --text-dim: #4a4a4a;
      --text-muted: #9a9a9a;
      --gold: #b07d1a;
      --gold-dim: rgba(180,130,30,0.08);
      --gold-mid: rgba(180,130,30,0.16);
      --teal: #1170a0;
      --teal-bright: #0e8fbf;
      --teal-dim: rgba(17,112,160,0.08);
      --rose: #b03555;
      --rose-dim: rgba(176,53,85,0.08);
      --sage: #357055;
      --sage-dim: rgba(53,112,85,0.08);
      --amber: #c06020;
      --amber-dim: rgba(192,96,32,0.08);
    }
  }
</style>
</head>
<body>
<div class="page">

  <!-- ─── HEADER ─── -->
  <header class="header">
    <div class="header-eyebrow">Executive Intelligence Report</div>
    <h1>The <em>Displacement</em> of Traditional Banking<br>by Digital Finance, 2015–2024</h1>
    <p class="header-sub">A cross-regional analysis of digital payment penetration, neobank user growth, branch network contraction, and regulatory license issuance across North America, Europe, Asia-Pacific, and Latin America.</p>
    <div class="header-meta">
