  </div>

  <!-- ─── ROW 2: Neobank growth + License wave ─── -->
  <div class="chart-grid chart-grid-2" style="margin-bottom:24px;">

    <!-- Chart 3: Neobank user surge by region -->
    <div class="chart-panel">
      <div class="panel-header">
        <div class="panel-insight-id">Insight 03 · Neobank User Surge</div>
        <div class="panel-title">Neobank Registered Users by Region (millions)</div>
        <div class="panel-desc">Stacked area view shows total market scale; individual bands reveal regional contribution. Asia-Pacific dominates with 498M users by 2024.</div>
      </div>
      <div class="chart-wrap" style="height:280px;">
        <canvas id="chart-neobank"></canvas>
      </div>
      <div class="legend">
        <div class="legend-item"><span class="legend-dot" style="background:#2cc6ef;"></span>Asia-Pacific</div>
        <div class="legend-item"><span class="legend-dot" style="background:#d4a73a;"></span>Europe</div>
        <div class="legend-item"><span class="legend-dot" style="background:#c94f6d;"></span>North America</div>
