        <div class="panel-title">New Digital Banking Licenses Approved per Year</div>
        <div class="panel-desc">Annual new approvals (derived from cumulative). Heavy clustering in 2019–2021 reflects coordinated regulatory opening across jurisdictions.</div>
      </div>
      <div class="chart-wrap" style="height:280px;">
        <canvas id="chart-licenses"></canvas>
      </div>
      <div class="legend">
        <div class="legend-item"><span class="legend-dot" style="background:#2cc6ef;"></span>Asia-Pacific</div>
        <div class="legend-item"><span class="legend-dot" style="background:#d4a73a;"></span>Europe</div>
        <div class="legend-item"><span class="legend-dot" style="background:#c94f6d;"></span>North America</div>
        <div class="legend-item"><span class="legend-dot" style="background:#4a9068;"></span>Latin America</div>
      </div>
    </div>

  </div>

  <!-- ─── ROW 3: Regional disparity radar / bar ─── -->
  <div class="chart-panel" style="margin-bottom:24px;">
    <div class="panel-header">
      <div class="panel-insight-id">Insight 05 · Regional Disparity in Fintech Disruption</div>
      <div class="panel-title">Comparative Disruption Scorecard: 2024 Snapshot Across Regions</div>
      <div class="panel-desc">Four metrics normalized to highlight pace and scale of disruption — digital payment penetration (%), neobank users (M), branch decline since 2015 (%), and cumulative digital licenses issued.</div>
    </div>
    <div class="chart-wrap" style="height:300px;">
      <canvas id="chart-regional"></canvas>
    </div>
    <div class="callout-row" style="margin-top:16px;">
      <div class="callout">
        <div class="callout-dot"></div>
        Asia-Pacific leads in user volume (498M neobank users) and penetration velocity (28.5% → 91.2%) but had a later branch-decline inflection
      </div>
      <div class="callout teal">
        <div class="callout-dot"></div>
        Europe leads in license issuance (78 cumulative) and has the sharpest proportional branch decline (−46%)
      </div>
      <div class="callout rose">
        <div class="callout-dot"></div>
        Latin America is the fastest-growing region in relative terms: 0 licenses in 2015 to 37 by 2024, penetration up 55pp
      </div>
    </div>
  </div>

  <!-- ─── FOOTER ─── -->
  <footer class="footer">
    <span class="footer-note">Source: composite regional estimates · digital_payment_penetration, traditional_bank_branches, neobank_users, digital_bank_licenses</span>
    <span class="footer-note">Fintech Disruption Report · 2015–2024</span>
  </footer>

</div>

<script>
/* ─────────────────────────────────────────────
   DATA (from source_data.json)
───────────────────────────────────────────── */
const YEARS = [2015,2016,2017,2018,2019,2020,2021,2022,2023,2024];
const YEARS_NEO = [2016,2017,2018,2019,2020,2021,2022,2023,2024];

// Digital payment penetration by region
const DPP = {
  'North America': [38.2,42.5,47.1,52.8,58.3,67.4,73.1,78.6,82.9,86.1],
  'Europe':        [35.0,39.8,44.2,50.1,56.7,64.3,70.8,76.2,80.5,84.0],
  'Asia-Pacific':  [28.5,35.2,43.8,52.6,61.0,71.5,78.3,83.7,87.9,91.2],
  'Latin America': [18.3,22.1,26.9,32.4,38.7,48.2,55.6,62.3,68.1,73.5],
};

// Traditional bank branches (thousands)
const BRANCHES = {
  'North America': [98.4,96.1,93.2,89.7,85.8,79.3,74.1,68.5,63.2,58.6],
  'Europe':        [182.3,176.8,169.5,160.2,150.1,137.6,126.3,115.8,106.4,98.1],
  'Asia-Pacific':  [312.5,315.8,314.2,308.6,298.4,281.2,263.7,245.1,228.3,213.5],
  'Latin America': [87.6,88.2,87.9,86.3,83.8,78.5,73.9,69.1,64.8,61.2],
};

// Neobank users (millions)
const NEOBANK = {
  'North America': [2.1,5.8,12.4,23.7,42.5,68.3,95.1,121.8,146.2],
  'Europe':        [3.5,9.2,19.8,38.1,65.4,98.7,132.5,163.2,189.6],
  'Asia-Pacific':  [8.3,22.6,51.4,98.7,172.3,261.8,348.2,425.6,498.3],
  'Latin America': [0.8,2.3,6.1,15.8,35.2,62.4,91.7,118.3,142.1],
};

// Digital bank licenses cumulative
const LICENSES_CUM = {
  'North America': [2,3,5,8,12,18,26,33,39,44],
  'Europe':        [4,7,12,19,28,38,51,62,71,78],
  'Asia-Pacific':  [3,5,9,15,24,37,52,65,76,85],
  'Latin America': [0,1,2,4,7,12,19,26,32,37],
};

/* ─────────────────────────────────────────────
   THEME HELPERS
───────────────────────────────────────────── */
const C = {
  apac:  '#2cc6ef',
  eu:    '#d4a73a',
  na:    '#c94f6d',
  latam: '#4a9068',
  apacA: 'rgba(44,198,239,0.18)',
  euA:   'rgba(212,167,58,0.18)',
  naA:   'rgba(201,79,109,0.18)',
  latamA:'rgba(74,144,104,0.18)',
  text:  '#7d8590',
  grid:  'rgba(255,255,255,0.05)',
};

const baseOpts = {
  responsive: true,
  maintainAspectRatio: false,
  plugins: {
    legend: { display: false },
    tooltip: {
      backgroundColor: '#1c2230',
      borderColor: 'rgba(212,167,58,0.3)',
      borderWidth: 1,
      titleColor: '#e6edf3',
      bodyColor: '#7d8590',
      padding: 10,
    }
  },
  scales: {
    x: {
      ticks: { color: C.text, font: { family: "'IBM Plex Mono'", size: 11 } },
      grid: { color: C.grid },
      border: { color: 'rgba(255,255,255,0.08)' },
    },
    y: {
      ticks: { color: C.text, font: { family: "'IBM Plex Mono'", size: 11 } },
      grid: { color: C.grid },
      border: { color: 'rgba(255,255,255,0.08)' },
    }
  }
};

function avgArr(arrays) {
  return arrays[0].map((_, i) => {
    const vals = arrays.map(a => a[i]);
    return vals.reduce((s, v) => s + v, 0) / vals.length;
  });
}

function sumArr(arrays) {
  return arrays[0].map((_, i) => arrays.map(a => a[i]).reduce((s, v) => s + v, 0));
}

/* ─────────────────────────────────────────────
   CHART 1: CROSSOVER — avg penetration + total branches
───────────────────────────────────────────── */
{
  const avgPen = avgArr(Object.values(DPP));
  const totalBranches = sumArr(Object.values(BRANCHES));

  const ctx = document.getElementById('chart-crossover').getContext('2d');
  new Chart(ctx, {
    type: 'line',
    data: {
      labels: YEARS,
      datasets: [
        {
          label: 'Avg Digital Payment Penetration (%)',
          data: avgPen,
          yAxisID: 'yPen',
          borderColor: C.apac,
          backgroundColor: 'rgba(44,198,239,0.06)',
          borderWidth: 2.5,
          tension: 0.35,
          fill: true,
          pointRadius: 3,
          pointBackgroundColor: C.apac,
        },
        {
          label: 'Total Bank Branches (000s)',
          data: totalBranches,
          yAxisID: 'yBranch',
          borderColor: C.na,
          backgroundColor: 'rgba(201,79,109,0.06)',
          borderWidth: 2.5,
          tension: 0.35,
          fill: true,
          pointRadius: 3,
          pointBackgroundColor: C.na,
          borderDash: [5,3],
        }
      ]
    },
    options: {
      ...baseOpts,
      interaction: { mode: 'index', intersect: false },
      plugins: {
        ...baseOpts.plugins,
        legend: { display: false },
        annotation: {},
      },
      scales: {
        x: baseOpts.scales.x,
        yPen: {
          type: 'linear',
          position: 'left',
          min: 0, max: 100,
          title: { display: true, text: 'Digital Penetration (%)', color: C.apac, font: { family: "'IBM Plex Mono'", size: 10 } },
          ticks: { color: C.apac, font: { family: "'IBM Plex Mono'", size: 10 }, callback: v => v + '%' },
          grid: { color: C.grid },
          border: { color: 'rgba(255,255,255,0.08)' },
        },
        yBranch: {
          type: 'linear',
          position: 'right',
          title: { display: true, text: 'Total Branches (000s)', color: C.na, font: { family: "'IBM Plex Mono'", size: 10 } },
          ticks: { color: C.na, font: { family: "'IBM Plex Mono'", size: 10 }, callback: v => v.toLocaleString() },
          grid: { drawOnChartArea: false },
          border: { color: 'rgba(255,255,255,0.08)' },
        }
      }
    }
  });
}

/* ─────────────────────────────────────────────
   CHART 2: BRANCH YoY DECLINE
───────────────────────────────────────────── */
{
  function yoy(arr) {
    return arr.slice(1).map((v, i) => parseFloat((v - arr[i]).toFixed(2)));
  }

  const yoyYears = YEARS.slice(1);
  const regions = ['North America','Europe','Asia-Pacific','Latin America'];
  const colors = [C.na, C.eu, C.apac, C.latam];

  const ctx = document.getElementById('chart-branch-yoy').getContext('2d');
  new Chart(ctx, {
    type: 'bar',
    data: {
      labels: yoyYears,
      datasets: regions.map((r, i) => ({
        label: r,
        data: yoy(BRANCHES[r]),
        backgroundColor: colors[i].replace(')', ',0.75)').replace('rgb','rgba').replace('#', 'rgba(').replace(/^rgba\(([0-9a-f]{2})([0-9a-f]{2})([0-9a-f]{2}),/, (m, r, g, b) => `rgba(${parseInt(r,16)},${parseInt(g,16)},${parseInt(b,16)},`),
        borderColor: colors[i],
        borderWidth: 1,
        borderRadius: 2,
      }))
    },
    options: {
      ...baseOpts,
      plugins: {
        ...baseOpts.plugins,
        legend: {
          display: true,
          position: 'bottom',
          labels: { color: C.text, font: { family: "'IBM Plex Mono'", size: 10 }, boxWidth: 10, padding: 12 }
        },
        tooltip: {
          ...baseOpts.plugins.tooltip,
          callbacks: { label: ctx => `${ctx.dataset.label}: ${ctx.parsed.y.toFixed(1)}k` }
        }
      },
      scales: {
        x: baseOpts.scales.x,
        y: {
          ...baseOpts.scales.y,
          title: { display: true, text: 'Annual Change (000 branches)', color: C.text, font: { family: "'IBM Plex Mono'", size: 10 } },
          ticks: { ...baseOpts.scales.y.ticks, callback: v => v + 'k' }
        }
      }
    }
  });
}

/* ─────────────────────────────────────────────
   CHART 3: NEOBANK STACKED AREA
───────────────────────────────────────────── */
{
  const ctx = document.getElementById('chart-neobank').getContext('2d');

  function hexToRgba(hex, a) {
    const r = parseInt(hex.slice(1,3),16);
    const g = parseInt(hex.slice(3,5),16);
    const b = parseInt(hex.slice(5,7),16);
    return `rgba(${r},${g},${b},${a})`;
  }

  new Chart(ctx, {
    type: 'line',
    data: {
      labels: YEARS_NEO,
      datasets: [
        { label: 'Asia-Pacific',  data: NEOBANK['Asia-Pacific'],  borderColor: C.apac,  backgroundColor: hexToRgba(C.apac, 0.55),  fill: true, tension: 0.4, borderWidth: 2, pointRadius: 3, stack: 'neo' },
        { label: 'Europe',        data: NEOBANK['Europe'],        borderColor: C.eu,    backgroundColor: hexToRgba('#d4a73a', 0.55), fill: true, tension: 0.4, borderWidth: 2, pointRadius: 3, stack: 'neo' },
        { label: 'North America', data: NEOBANK['North America'], borderColor: C.na,    backgroundColor: hexToRgba(C.na, 0.55),   fill: true, tension: 0.4, borderWidth: 2, pointRadius: 3, stack: 'neo' },
        { label: 'Latin America', data: NEOBANK['Latin America'], borderColor: C.latam, backgroundColor: hexToRgba(C.latam, 0.55), fill: true, tension: 0.4, borderWidth: 2, pointRadius: 3, stack: 'neo' },
      ]
    },
    options: {
      ...baseOpts,
      interaction: { mode: 'index', intersect: false },
      plugins: {
        ...baseOpts.plugins,
        tooltip: {
          ...baseOpts.plugins.tooltip,
          callbacks: { label: ctx => `${ctx.dataset.label}: ${ctx.parsed.y.toFixed(1)}M` }
        }
      },
      scales: {
        x: baseOpts.scales.x,
        y: {
          ...baseOpts.scales.y,
          stacked: true,
          title: { display: true, text: 'Neobank Users (millions)', color: C.text, font: { family: "'IBM Plex Mono'", size: 10 } },
          ticks: { ...baseOpts.scales.y.ticks, callback: v => v + 'M' }
        }
      }
    }
  });
}

/* ─────────────────────────────────────────────
   CHART 4: ANNUAL NEW LICENSES (derived from cumulative)
───────────────────────────────────────────── */
{
  function annualNew(arr) {
    return arr.slice(1).map((v, i) => v - arr[i]);
  }

  const licYears = YEARS.slice(1); // 2016–2024
  const ctx = document.getElementById('chart-licenses').getContext('2d');

  function hexToRgba(hex, a) {
    const r = parseInt(hex.slice(1,3),16);
    const g = parseInt(hex.slice(3,5),16);
    const b = parseInt(hex.slice(5,7),16);
    return `rgba(${r},${g},${b},${a})`;
  }

  new Chart(ctx, {
    type: 'bar',
    data: {
      labels: licYears,
      datasets: [
        { label: 'Asia-Pacific',  data: annualNew(LICENSES_CUM['Asia-Pacific']),  backgroundColor: hexToRgba(C.apac, 0.8),  borderColor: C.apac,  borderWidth: 1, borderRadius: 2 },
        { label: 'Europe',        data: annualNew(LICENSES_CUM['Europe']),        backgroundColor: hexToRgba('#d4a73a', 0.8), borderColor: C.eu,    borderWidth: 1, borderRadius: 2 },
        { label: 'North America', data: annualNew(LICENSES_CUM['North America']), backgroundColor: hexToRgba(C.na, 0.8),   borderColor: C.na,    borderWidth: 1, borderRadius: 2 },
        { label: 'Latin America', data: annualNew(LICENSES_CUM['Latin America']), backgroundColor: hexToRgba(C.latam, 0.8), borderColor: C.latam, borderWidth: 1, borderRadius: 2 },
      ]
    },
    options: {
      ...baseOpts,
      plugins: {
        ...baseOpts.plugins,
        legend: {
          display: true,
          position: 'bottom',
          labels: { color: C.text, font: { family: "'IBM Plex Mono'", size: 10 }, boxWidth: 10, padding: 12 }
        },
        tooltip: {
          ...baseOpts.plugins.tooltip,
          callbacks: { label: ctx => `${ctx.dataset.label}: ${ctx.parsed.y} new licenses` }
        }
      },
      scales: {
        x: baseOpts.scales.x,
        y: {
          ...baseOpts.scales.y,
          stacked: true,
          title: { display: true, text: 'New Licenses Approved (annual)', color: C.text, font: { family: "'IBM Plex Mono'", size: 10 } },
          ticks: { ...baseOpts.scales.y.ticks }
        }
      }
    }
  });
}

/* ─────────────────────────────────────────────
   CHART 5: REGIONAL DISPARITY — grouped horizontal bar
───────────────────────────────────────────── */
{
  const ctx = document.getElementById('chart-regional').getContext('2d');

  const regions = ['North America','Europe','Asia-Pacific','Latin America'];
  const colors = [C.na, C.eu, C.apac, C.latam];

  // 2024 values
  const pen2024   = regions.map(r => DPP[r][9]);
  // Branch decline % since 2015
  const bDecline  = regions.map(r => parseFloat(((BRANCHES[r][9] - BRANCHES[r][0]) / BRANCHES[r][0] * 100).toFixed(1)));
  // Neobank users 2024 (M) - scaled to percentage of max for visual comparison
  const neo2024   = regions.map(r => NEOBANK[r][8]);
  // Cumulative licenses 2024
  const lic2024   = regions.map(r => LICENSES_CUM[r][9]);

  new Chart(ctx, {
    type: 'bar',
    data: {
      labels: regions,
      datasets: [
        {
          label: 'Digital Penetration 2024 (%)',
          data: pen2024,
          backgroundColor: colors.map(c => {
            const r = parseInt(c.slice(1,3),16), g = parseInt(c.slice(3,5),16), b = parseInt(c.slice(5,7),16);
            return `rgba(${r},${g},${b},0.85)`;
          }),
          borderColor: colors,
